    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:ANTHROPIC_BASE_URL]/v1/claude_code/routines/trig_019ysxedonGvJiDzVZbJamBd/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      }
    },
    "dailyHour": 4,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  },
  "engineVersion": "60823.1"
}

